// sandbox: the only operations a behaviour is handed
type Sandbox struct {
    Audio *audio.Engine
    FX    *particles.System
}
func (s *Sandbox) PlaySound(id SoundID, volume float64) { s.Audio.Play(id, volume) }
func (s *Sandbox) SpawnParticles(t ParticleType, n int) { s.FX.Spawn(t, n) }

type Power interface{ Activate(sb *Sandbox) }   // one method per behaviour

type SkyLaunch struct{}

func (SkyLaunch) Activate(sb *Sandbox) {          // composes primitives only
    sb.PlaySound(SoundSproing, 1.0)
    sb.SpawnParticles(ParticleDust, 10)
}
